/**
 * The non-blocking toast that says what of a world this browser cannot
 * show: its words and a button that puts it away. It takes no pointer
 * events itself; only the button does.
 *
 * Fetched the first time a world has something to tell (feedbackSurface.ts),
 * so a world this browser shows in full pays nothing for it.
 */

/** The toast saying `text`, not yet on the page. `dismissed` is called when its button is pressed. */
export function buildToast(doc: Document, text: string, dismissed: () => void): HTMLElement {
  const toast = doc.createElement('div');
  toast.setAttribute('data-webverse-feedback-toast', '');
  toast.setAttribute('role', 'status');
  toast.setAttribute('aria-live', 'polite');
  toast.style.cssText =
    'position:fixed;right:12px;bottom:12px;z-index:10;max-width:min(420px,80vw);' +
    'display:flex;align-items:center;gap:10px;padding:10px 12px;border-radius:6px;' +
    'background:var(--webverse-feedback-bg,#101014);color:var(--webverse-feedback-fg,#dfe3ea);' +
    'border:1px solid rgba(223,227,234,0.35);font:13px/1.4 system-ui,sans-serif;' +
    'pointer-events:none;';
  const words = doc.createElement('span');
  words.textContent = text;
  toast.appendChild(words);
  const dismiss = doc.createElement('button');
  dismiss.type = 'button';
  dismiss.setAttribute('data-webverse-feedback-toast-dismiss', '');
  dismiss.setAttribute('aria-label', 'Dismiss');
  dismiss.textContent = '×';
  dismiss.style.cssText =
    'pointer-events:auto;font:inherit;color:inherit;background:transparent;' +
    'border:1px solid currentColor;border-radius:4px;padding:0 8px;cursor:pointer;';
  dismiss.addEventListener('click', dismissed);
  toast.appendChild(dismiss);
  return toast;
}
